int main() {
    int K, A, B;
    cin >> K >> A >> B;
    int m = max(1, ceil(log2(A)));
    int res = 0;
    while (K>0) {
        res += pow(2, m)*(K - (B << (m - 1)));
        B = B << m;
        K -= (K >> (m - 1)) << (m - 1);
        m = max(1, ceil(log2(K)));
    }
    cout << res;
    return 0;
}
